export type GridKey = keyof typeof gridStrings.en;

const StringsContext = createContext<Dicts>(gridStrings);

export function StringsProvider({ strings, children }: { strings?: Dicts; children: ReactNode }) {
  const merged = useMemo<Dicts>(
    () => ({ en: { ...gridStrings.en, ...strings?.en }, ar: { ...gridStrings.ar, ...strings?.ar } }),
    [strings],
  );
  return <StringsContext.Provider value={merged}>{children}</StringsContext.Provider>;
}

export function translate(dicts: Dicts, locale: Locale, key: string) {
  return dicts[locale][key] ?? dicts.en[key] ?? key;
}

// An app narrows the key type with `useT<AppKey | GridKey>()`.
export function useT<K extends string = GridKey>() {
  const { locale } = usePrefs();
  const dicts = useContext(StringsContext);
  return (key: K, vars?: Record<string, string | number>) => {
    let s = translate(dicts, locale ?? 'en', key);
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace(`{${k}}`, String(v));
    return s;
  };
}

// The one place that must speak a language before it is saved: the first-run picker previews
// the option being selected.
export function useTranslateIn() {
  const dicts = useContext(StringsContext);
  return (locale: Locale, key: string) => translate(dicts, locale, key);
}
